/**
 * Get an inline SVG icon string by name.
 * @param {string} name - Lucide icon name (e.g., 'credit-card', 'users', 'zap')
 * @param {number} [size=18] - Width and height in pixels
 * @param {string} [cls=''] - Additional CSS classes
 * @returns {string} Fully formed, valid <svg> HTML string
 */
function icon(name, size, cls) {
  size = size || 18;
  cls = cls ? ' ' + cls : '';
  const content = ICON_PATHS[name];
  if (!content) {
    console.warn('[icons] Unknown icon:', name);
    return '<span class="icon-missing"></span>';
  }
  return '<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide-icon' + cls + '">' + content + '</svg>';
}

/**
 * Map for backwards-compatible object lookups
 */
const ICON_SVG_MAP = {};
for (const k of Object.keys(ICON_PATHS)) {
  ICON_SVG_MAP[k] = icon(k, 24);
}

/**
 * Scan DOM for elements with [data-icon] and inject the corresponding SVG markup.
 * @param {HTMLElement|Document} [root=document]
 */
function hydrateIcons(root) {
  const container = root || document;
  container.querySelectorAll('[data-icon]').forEach(function(el) {
    const name = el.getAttribute('data-icon');
    const size = parseInt(el.getAttribute('data-icon-size') || '18', 10);
    const cls = el.getAttribute('data-icon-class') || '';
    if (name) {
      el.innerHTML = icon(name, size, cls);
    }
  });
}

/**
 * Generate initials from a person's name for monogram avatars.
 * @param {string} name - Full name (e.g. "Rahul Sharma")
 * @returns {string} 1-2 character uppercase initials (e.g. "RS")
 */
function getInitials(name) {
  if (!name || typeof name !== 'string') return '?';
  const parts = name.trim().split(/\s+/);
  if (parts.length === 0 || !parts[0]) return '?';
  if (parts.length === 1) {
    return parts[0].substring(0, 2).toUpperCase();
  }
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

/** Predefined palette of 8 distinct accent colors for user profiles */
const MONOGRAM_PALETTE = [
  '#D9822B', // Amber Gold (Default)
  '#10B981', // Emerald
  '#3B82F6', // Blue
  '#8B5CF6', // Purple
  '#EC4899', // Pink
  '#F59E0B', // Amber
  '#06B6D4', // Cyan
  '#F43F5E'  // Rose
];

/**
 * Pick a deterministic color from the palette based on string hash.
 * @param {string} name
 * @returns {string} Hex color code
 */
function getAvatarColor(name) {
  if (!name) return MONOGRAM_PALETTE[0];
  let hash = 0;
  for (let i = 0; i < name.length; i++) {
    hash = name.charCodeAt(i) + ((hash << 5) - hash);
  }
  const idx = Math.abs(hash) % MONOGRAM_PALETTE.length;
  return MONOGRAM_PALETTE[idx];
}

/**
 * Render a complete circular monogram avatar HTML string.
 * @param {string} name - Person name
 * @param {number} [size=32] - Avatar circle diameter in pixels
 * @param {string} [colorOverride] - Optional hex color override
 * @param {string} [extraClass=''] - Additional CSS class
 * @returns {string} HTML snippet for monogram badge
 */
function renderMonogram(name, size, colorOverride, extraClass) {
  size = size || 32;
  const initials = getInitials(name);
  const color = colorOverride || getAvatarColor(name);
  const fontSize = Math.round(size * 0.42);
  const cls = extraClass ? ' ' + extraClass : '';
  return '<span class="avatar-monogram' + cls + '" style="width:' + size + 'px;height:' + size + 'px;border-color:' + color + ';color:' + color + ';font-size:' + fontSize + 'px;" title="' + (name || '') + '">' + initials + '</span>';
}

// Auto-hydrate icons on DOMContentLoaded if running in browser
if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => hydrateIcons());
  } else {
    hydrateIcons();
  }
}
